"""
example payload:
{
	"mode":"add",
	"path":,"armorClass.bonus",
	"value":2
}
"""

# read payload
mode = payload["mode"]
path = payload["path"]
value = payload["value"]

if mode == "setRaw":
	self.Set(path, value)

elif mode == "setRef":
	self.Set(path, self.Get(value))

elif mode == "addRaw":
	self.Set(path, self.Get(path) + value)

elif mode == "addRef":
	self.Set(path, self.Get(path) + self.Get(value))

elif mode == "minusRaw":
	self.Set(path, self.Get(path) - value)

elif mode == "minusRef":
	self.Set(path, self.Get(path) - self.Get(value))

if False: # debug
	system.perspective.print("Set {} to {}".format(path, value))
